*** Add File: script.js
+const form = document.querySelector("#contactForm");
+const fields = {
+  fullName: {
+    input: document.querySelector("#fullName"),
+    error: document.querySelector("#fullNameError"),
+    validate(value) {
+      if (!value.trim()) {
+        return "Enter your full name.";
+      }
+
+      if (value.trim().length < 2) {
+        return "Full name must be at least 2 characters.";
+      }
+
+      return "";
+    },
+  },
+  email: {
+    input: document.querySelector("#email"),
+    error: document.querySelector("#emailError"),
+    validate(value) {
+      if (!value.trim()) {
+        return "Enter your email address.";
+      }
+
+      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
+      if (!emailPattern.test(value.trim())) {
+        return "Enter a valid email address.";
+      }
+
+      return "";
+    },
+  },
+  phone: {
+    input: document.querySelector("#phone"),
+    error: document.querySelector("#phoneError"),
+    validate(value) {
+      const trimmedValue = value.trim();
+      if (!trimmedValue) {
+        return "";
+      }
+
+      const phonePattern = /^\+?[\d\s()-]{7,20}$/;
+      if (!phonePattern.test(trimmedValue)) {
+        return "Use a valid phone number format.";
+      }
+
+      return "";
+    },
+  },
+};
+
+const successMessage = document.querySelector("#successMessage");
+
+function setFieldState(field, message) {
+  field.error.textContent = message;
+  field.input.classList.toggle("invalid", Boolean(message));
+  field.input.setAttribute("aria-invalid", String(Boolean(message)));
+}
+
+function validateField(field) {
+  const message = field.validate(field.input.value);
+  setFieldState(field, message);
+  return !message;
+}
+
+Object.values(fields).forEach((field) => {
+  field.input.addEventListener("blur", () => {
+    validateField(field);
+  });
+
+  field.input.addEventListener("input", () => {
+    if (field.input.classList.contains("invalid")) {
+      validateField(field);
+    }
+
+    successMessage.textContent = "";
+  });
+});
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  const isValid = Object.values(fields).every(validateField);
+
+  if (!isValid) {
+    const firstInvalidField = Object.values(fields).find((field) =>
+      field.input.classList.contains("invalid")
+    );
+    firstInvalidField.input.focus();
+    successMessage.textContent = "";
+    return;
+  }
+
+  form.reset();
+  Object.values(fields).forEach((field) => setFieldState(field, ""));
+  successMessage.textContent = "Thanks! Your support request details are ready to send.";
+});
*** End Patch
